<?php require 'config.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM restaurants WHERE id=? AND approved=1");$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Restaurant not found');}$s=$pdo->prepare("SELECT * FROM foods WHERE restaurant_id=? AND available=1 ORDER BY name");$s->execute([$id]);$foods=$s->fetchAll();$pageTitle=$r['name'];include 'partials/header.php';?>
<h1><?=e($r['name'])?></h1><p class="muted"><?=e($r['area'])?> · <?=e($r['address'])?></p><p><?=e($r['description'])?></p><div class="grid"><?php foreach($foods as $f):?><article class="card"><div class="food-emoji">🍛</div><h3><?=e($f['name'])?></h3><p class="muted"><?=e($f['description'])?></p><p class="price">৳<?=number_format((float)$f['price'],2)?></p><form method="post" action="cart.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="food_id" value="<?=$f['id']?>"><button class="btn">Add to cart</button></form></article><?php endforeach;?><?php if(!$foods):?><p>This restaurant has not added food yet.</p><?php endif;?></div><?php include 'partials/footer.php';?>
